def determinar_polaridad(n):
    if n > 0:
        return 'Positivo'
    elif n < 0:
        return 'Negativo'
    else:
        return 'Cero'

for val in [10, -5, 0]:
    print(f'Número {val}: {determinar_polaridad(val)}')

