def mayor_de_tres_anidado(a, b, c):
    if a > b:
        if a > c:
            return a
        else:
            return c
    else:
        if b > c:
            return b
        else:
            return c

print('Mayor de (12, 45, 30):', mayor_de_tres_anidado(12, 45, 30))

def clasificar_triangulo(a, b, c):
    if (a + b > c) and (a + c > b) and (b + c > a):
        if a == b == c:
            return 'Equilátero'
        elif a == b or a == c or b == c:
            return 'Isósceles'
        else:
            return 'Escaleno'
    return 'No forma un triángulo válido'

print('(5,5,5):', clasificar_triangulo(5,5,5))
print('(5,5,8):', clasificar_triangulo(5,5,8))
print('(3,4,5):', clasificar_triangulo(3,4,5))
print('(1,2,10):', clasificar_triangulo(1,2,10))

def calcular_descuento(monto):
    if monto < 100:
        desc = 0.0
    elif monto < 300:
        desc = 0.05
    elif monto < 700:
        desc = 0.10
    else:
        desc = 0.15
    total = monto * (1 - desc)
    return f'Monto: {monto:.2f} Bs | Descuento: {desc*100:.0f}% | Total a pagar: {total:.2f} Bs'

print(calcular_descuento(80))
print(calcular_descuento(250))
print(calcular_descuento(500))
print(calcular_descuento(1000))

def es_bisiesto(anio):
    if (anio % 4 == 0 and anio % 100 != 0) or (anio % 400 == 0):
        return 'Es bisiesto'
    return 'No es bisiesto'

for y in [2000, 1900, 2024, 2026]:
    print(f'Año {y}: {es_bisiesto(y)}')

def evaluar_imc(peso, estatura):
    imc = peso / (estatura ** 2)
    if imc < 18.5:
        estado = 'Bajo peso'
    elif imc < 25:
        estado = 'Normal'
    elif imc < 30:
        estado = 'Sobrepeso'
    else:
        estado = 'Obesidad'
    return f'IMC: {imc:.2f} ({estado})'

print(evaluar_imc(50, 1.70))
print(evaluar_imc(68, 1.75))
print(evaluar_imc(82, 1.70))
print(evaluar_imc(98, 1.65))

def validar_password(clave):
    if len(clave) < 8:
        return 'Inválida: Debe tener al menos 8 caracteres'
    if not any(c.isdigit() for c in clave):
        return 'Inválida: Debe contener al menos un número'
    if not any(c.isupper() for c in clave):
        return 'Inválida: Debe contener al menos una letra mayúscula'
    return 'Contraseña VÁLIDA'

print('"abc":', validar_password('abc'))
print('"password":', validar_password('password'))
print('"Password":', validar_password('Password'))
print('"Password123":', validar_password('Password123'))

def calculadora(n1, n2, op):
    if op == 1:
        return f'Suma: {n1 + n2}'
    elif op == 2:
        return f'Resta: {n1 - n2}'
    elif op == 3:
        return f'Multiplicación: {n1 * n2}'
    elif op == 4:
        if n2 != 0:
            return f'División: {n1 / n2}'
        return 'Error: No se puede dividir entre cero'
    else:
        return 'Opción no válida'

print(calculadora(10, 5, 1))
print(calculadora(10, 5, 4))
print(calculadora(10, 0, 4))

def evaluar_cuadrante(x, y):
    if x == 0 and y == 0:
        return 'Origen (0,0)'
    elif x == 0:
        return 'Sobre el Eje Y'
    elif y == 0:
        return 'Sobre el Eje X'
    elif x > 0 and y > 0:
        return 'Cuadrante I'
    elif x < 0 and y > 0:
        return 'Cuadrante II'
    elif x < 0 and y < 0:
        return 'Cuadrante III'
    else:
        return 'Cuadrante IV'

print('(3, 5):', evaluar_cuadrante(3, 5))
print('(-2, 4):', evaluar_cuadrante(-2, 4))
print('(-1, -7):', evaluar_cuadrante(-1, -7))
print('(4, -3):', evaluar_cuadrante(4, -3))
print('(0, 0):', evaluar_cuadrante(0, 0))
print('(0, 8):', evaluar_cuadrante(0, 8))
